  accountButton=button("Sign in");accountButton.setOnClickListener(v->{if(status.optBoolean("rootLocked"))unlock(false,null,this::showLogin);else showLogin();});logoutButton=button("Sign out");logoutButton.setOnClickListener(v->call("account.logout",obj(),result->{clearAccount();refreshStatus();notice.setText("Signed out. Node keeps its own lifetime.");}));importButton=button("Import profile");importButton.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,IMPORT);});createButton=button("Create profile");createButton.setOnClickListener(v->{if(!status.optBoolean("profileExists"))createProfile();else if(status.optBoolean("rootLocked"))unlock(false,null,this::createAccount);else createAccount();});
